def list_identity_pools(self, max_results: int) -> str:
    """
    List all identity pools with a limit of max_results
    """
    identity_pools = []

    # Get the pools up to max_results
    count = 0
    for identity_pool_id, pool in self.identity_pools.items():
        if count >= max_results:
            break

        identity_pools.append({
            "IdentityPoolId": pool.identity_pool_id,
            "IdentityPoolName": pool.identity_pool_name
        })
        count += 1

    return json.dumps({"IdentityPools": identity_pools})

def delete_identity_pool(self, identity_pool_id: str) -> None:
    self.describe_identity_pool(identity_pool_id)

    del self.identity_pools[identity_pool_id]

